use vstd::prelude::*;

verus! {
    // copy takes a Vec<i8> and returns a fresh Vec<i8> containing the same elements
    fn copy(arr: &Vec<i8>) -> (result: Vec<i8>)
        ensures
            // the result has the same length as the input
            result.len() == arr.len(),
        ensures
            // and the same contents
            result.as_seq() == arr.as_seq(),
    {
        let mut result = Vec::with_capacity(arr.len());
        // iterate over every element in arr, pushing it into result
        for &value in arr.iter()
            // at each iteration, result.len() is how many items we've copied so far
            invariant
                result.len() <= arr.len(),
            // and the slice of arr from 0 to result.len() matches result exactly
            invariant
                result.as_seq() == Seq::slice(arr.as_seq(), 0, result.len()),
            // this strictly decreases each time through the loop
            decreases
                arr.len() - result.len(),
        {
            result.push(value);
        }
        result
    }
}

